create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
create function pg_temp.fails(statement text,expected text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then perform pg_temp.ok(true,label);return;end if;raise;end;raise exception 'Unexpected success: %',label;end $$;
update private.memory_publication_settings set writes_enabled=true,minihomes_enabled=true,policy_revision='ELIGIBILITY_LOCAL_PUBLIC';
select set_config('request.jwt.claim.sub','77777777-7777-4777-8777-777777777777',false);
select set_config('test.public.selection','{"nickname":"Synthetic public","bio":"","entries":[]}',false);
set role authenticated;
select pg_temp.fails($q$select public.prepare_memory_minihome(0,current_setting('test.public.selection')::jsonb)$q$,'ELIGIBILITY_POLICY_UNAVAILABLE','public eligibility defaults disabled');
reset role;
update private.memory_eligibility_policies set enabled=true,revision='LOCAL_PUBLIC' where purpose='PUBLIC_PUBLISH';
update private.memory_eligibility_evidence set state='GRANTED',expires_at=clock_timestamp()+interval '1 hour' where purpose='CLOUD_WRITE';
set role authenticated;
select pg_temp.fails($q$select public.prepare_memory_minihome(0,current_setting('test.public.selection')::jsonb)$q$,'ELIGIBILITY_REQUIRED','private cloud grant does not permit public preparation');
reset role;
insert into private.memory_eligibility_evidence values('77777777-7777-4777-8777-777777777777','PUBLIC_PUBLISH','LOCAL_PUBLIC','GRANTED',gen_random_uuid(),clock_timestamp()+interval '1 hour',1);
